N, M = MAP()
G = list2d(N, N, 0)
for i in range(M):
    a, b = MAP()
    a -= 1
    b -= 1
    G[a][b] = G[b][a] = 1
# dp[S][i] := 訪問済の頂点集合をSとして、最後に頂点iにいる場合の通り数
dp = list2d(1 << N, N, 0)
# 最初は頂点1にいる状態から
dp[1][0] = 1
for S in range(1, 1 << N):
    for i in range(N):
        # iが遷移元に含まれていない
        if not S & 1 << i:
            continue
        for j in range(N):
            # jが遷移元に含まれている(ので遷移先にはできない)
            if S & 1 << j:
                continue
            # 辺の張られた頂点間であれば遷移させる
            if G[i][j]:
                dp[S | 1 << j][j] += dp[S][i]
# 全頂点訪問できた通り数を合計する
ans = sum(dp[(1 << N) - 1])
print(ans)

