# @mt
def slv(H, N, AB):
    dp = [INF] * (H + 1)
    dp[0] = 0
    for a, b in AB:
        for h, bb in enumerate(dp):
            if bb == INF:
                continue
            n = min(H, h + a)
            dp[n] = min(dp[n], bb + b)
    return dp[-1]


