from collections import deque


def bfs(grid, sy, sx, wall):
    queue = deque([])
    queue.append([sy, sx, 0])
    visited = {}
    visited[(sy, sx)] = 0
    dxy = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    while queue:
        y, x, cnt = queue.popleft()
        for dy, dx in dxy:
            y_, x_ = y + dy, x + dx
            if grid[y_][x_] == wall or (y_, x_) in visited:
                continue
            queue.append([y_, x_, cnt + 1])
            visited[(y_, x_)] = cnt + 1
    return max(visited.values())


