from math import gcd
import numpy as np


def sum_gcd(k: int) -> int:
    # a > b > c
    sum_p1 = 0
    for h in range(1, k + 1):
        for i in range(1, h):
            for j in range(1, i):
                sum_p1 += gcd(gcd(h, i), j)
    # a = b > c and a > b = c
    sum_p2 = 0
    for h in range(1, k + 1):
        for i in range(1, h):
            sum_p2 += gcd(h, i)
    # a = b = c
    sum_p3 = k * (k + 1) // 2
    answer = sum_p1 * 6 + sum_p2 * 6 + sum_p3
    return answer


def main():
    k = int(input().rstrip())
    print((sum_gcd(k)))


if __name__ == "__main__":
    main()

