    fact[i] = (fact[i - 1] * i) % MOD
    invfact[i] = mod_pow(fact[i], MOD - 2) % MOD


def comb(n, r):
    if n < r or n == 0 or r == 0:
        return 0
    return (((fact[n] * invfact[r]) % MOD) * invfact[n - r]) % MOD


