toID = {i: j for i, j in zip(B, list(range(1, M + 1)))}
dp = SegmentTree([0] * (M + 1))
ans = [0] * N
before = [0] * N


def dfs(v, p=-1):
    idx = toID[A[v]]
    a = dp.query(0, idx) + 1
    before[v] = dp.query(idx, idx + 1)
    flag = False
    if before[v] < a:
        flag = True
        dp.update(idx, a)
    before_max = dp.query(0, M + 1)
    ans[v] = max(before_max, a)
    for e in G[v]:
        if e == p:
            continue
        dfs(e, v)
    if flag:
        dp.update(idx, before[v])


dfs(0)
print(("\n".join(map(str, ans))))

