    count = 0
    xcount = 0
    while n > 1 and x <= len(kv):
        for x in list(kv.keys()):
            for y in range(1, kv[x] + 1, +1):
                if n % (x**y) == 0:
                    count = count + 1
                    n = n // (x**y)
                    xcount = xcount + y
                else:
                    break
    print(count)


