def sieve(n):
    is_prime = [1] * (n + 1)
    is_prime[0], is_prime[1] = 0, 0
    for i in range(2, n + 1):
        if not is_prime[i]:
            continue
        j = i * 2
        while j <= n:
            is_prime[j] = 0
            j += i
    return is_prime


