import copy

N = eval(input())


def nine(m):
    if m < 9:
        return m
    for i in range(1000):
        t = 9**i
        if t > m:
            t1 = 9 ** (i - 1)
            return m - t1


def six(m):
    if m < 6:
        return m
    for i in range(1000):
        t = 6**i
        if t > m:
            t2 = 6 ** (i - 1)
            return m - t2


Z = 15
k = 1 << Z
b = set()
for i in range(k):
    n = copy.deepcopy(N)
    ans = 0
    for j in range(Z):
        if n < 6:
            b.add(ans + n)
            break
        if i & (1 << j) != 0:
            # 9
            n = nine(n)
            ans += 1
        else:
            # 6
            n = six(n)
            ans += 1
print(min(b))

