def eratosthenes_sieve(n):
    """素数列挙(エラトステネスの篩)"""
    table = [0] * (n + 1)
    prime_list = []
    for i in range(2, n + 1):
        if table[i] == 0:
            prime_list.append(i)
            for j in range(i + i, n + 1, i):
                table[j] = 1
    return prime_list


N = 100000
primes = set(eratosthenes_sieve(N + 1))
A = [0] * (N + 1)
for a in range(1, N + 1, 2):
    if a in primes and (a + 1) // 2 in primes:
        A[a] = 1
acc = [0] + list(accumulate(A))
for i in range(INT()):
    l, r = MAP()
    ans = acc[r + 1] - acc[l]
    print(ans)

