memo = {}


def f(x):
    if 0 <= x <= 5:
        return x
    if x in memo:
        return memo[x]
    k = 0
    while 9**k <= x:
        k += 1
    m = 0
    while 6**m <= x:
        m += 1
    memo[x] = min(f(x - 9 ** (k - 1)) + 1, f(x - 6 ** (m - 1)) + 1)
    return memo[x]


