def chmin(a, b):
    return b if a > b else a


def chmax(a, b):
    return b if a < b else a


def main(N, h):
    INF = 10**9
    dp = [INF] * (10**5 + 10)
    dp[0] = 0
    dp[1] = abs(h[1] - h[0])
    for i in range(2, N):
        dp[i] = chmin(dp[i], dp[i - 1] + abs(h[i] - h[i - 1]))
        dp[i] = chmin(dp[i], dp[i - 2] + abs(h[i] - h[i - 2]))
    return dp[N - 1]


