def f(n, edges, s):
    all_visited = True
    for i in range(n):
        if visited[i] == False:
            all_visited = False
            break
    if all_visited:
        return
    for x, c in edges[s]:
        if visited[x]:
            continue
        if ans[s] == 0:
            if c % 2 == 1:
