import itertools
import sys

sys.setrecursionlimit(10000)
INF = float("inf")
N = int(sys.stdin.readline())
A = [list(map(int, sys.stdin.readline().split())) for _ in range(N)]


def solve():
    # 消していいやつ
    useless = [[0] * N for _ in range(N)]
    # 1 つ経由するのだけ考えれば OK
    for st, en in itertools.combinations(list(range(N)), r=2):
        for via in range(N):
            if via in [st, en]:
                continue
            if A[st][via] + A[via][en] < A[st][en]:
                return -1
            if A[st][via] + A[via][en] == A[st][en]:
                useless[st][en] = True
                useless[en][st] = True
    return (
        sum(
            [
                A[s][e]
                for s, e in itertools.product(list(range(N)), repeat=2)
                if not useless[s][e]
            ]
        )
        // 2
    )


print((solve()))

