    return "".join(tmp)


def breadth_first_search(answers):
    q = [[0, "01234567"]]
    while len(q) != 0:
        g, field = q.pop(0)
        a = field.find("0")
        for b in MOVE[a]:
            tmp = swap(field, a, b)
            if not tmp in answers:
                answers[tmp] = g + 1
                q.append([g + 1, tmp])
    return answers


answers = breadth_first_search(answers)
