def find_power(n, mod):
    # 0!からn!までのびっくりを出してくれる関数(ただし、modで割った値に対してである）
    powlist = [0] * (n + 1)
    powlist[0] = 1
    powlist[1] = 1
    for i in range(2, n + 1):
        powlist[i] = powlist[i - 1] * i % (mod)
    return powlist


def find_inv_power(n):
    # 0!からn!までの逆元を素数10**9+7で割ったあまりリストを作る関数
    powlist = find_power(n, 10**9 + 7)
    check = powlist[-1]
