edges = [None] * M
for i in range(M):
    x, y = MAP()
    nodes[x - 1].append(y - 1)
    edges[i] = (x - 1, y - 1)
memo = [-1] * N
# メモ化再帰
def dfs(cur):
    if memo[cur] != -1:
        return memo[cur]
    mx = 0
    for dest in nodes[cur]:
        mx = max(mx, dfs(dest) + 1)
    memo[cur] = mx
    return mx


