    B = 0
    bm = Counter()
    bm[0] += 1
    for i in range(1, N + 1):
        B = A[i - 1] + B
        bm[B % M] += 1
    ans = 0
    for v in bm.values():
        if v > 1:
            ans += (v * (v - 1)) // 2
    return ans


