def Con(V, E):
    C1, C2 = set(), set()
    C1.add(1)
    while len(C1) > len(C2):
        for v in V:
            if v in C1 and v not in C2:
                for e in E:
                    if e[0] == v:
                        C1.add(e[1])
                    elif e[1] == v:
                        C1.add(e[0])
                C2.add(v)
    if len(C1) == len(V):
        return True
    else:
        return False


