memo = [{} for _ in range(N + 1)]


def isAGC(char4):
    for i in range(4):
        tmp = list(char4)
        if i != 3:
            tmp[i], tmp[i + 1] = tmp[i + 1], tmp[i]
        if "".join(tmp).count("AGC") >= 1:
            return True
    return False


def dfs(cur, char3):
    if char3 in memo[cur]:
        return memo[cur][char3]
    if cur == N:
        return 1
    ret = 0
    for c in ["A", "C", "G", "T"]:
        if not isAGC(char3 + c):
            ret = (ret + dfs(cur + 1, char3[1:] + c)) % MOD
    memo[cur][char3] = ret
    return ret


