def solve():
    N, A, B, C, D = list(map(int, input().split()))
    A, B = 0, B - A
    if B < 0:
        B *= -1
    M = N - 1
    for i in range(0, N, 2):
        if C * (M - i) <= B <= (D - C) * ((i + 1) / 2) + D * (M - i):
