    inv = (inv + modinv(A[i], P)) % P
    l = fctr1(A[i])
    for j in range(len(l)):
        e[l[j][0]] = max(e[l[j][0]], l[j][1])
ans = 1
for k in list(e.keys()):
    if e[k] != 0:
        for i in range(e[k]):
            ans = ans * k % P
ans = ans * inv % P
print(ans)

