    dp = [j for j in range(x + 1)]
    for i in range(n):
        si = s[i]
        ndp = [0] * (x + 1)
        for j in range(x + 1):
            nd = dp[j % si]  # 先頭にsiを挿入 (スタートの値がj%siとなる)
            nd += i * dp[j]  # 先頭以外にsiを挿入 (スタートの値も間の値も変わらない)
            ndp[j] += nd
            if ndp[j] >= mod:
                ndp[j] %= mod
        dp = [j for j in ndp]
    print((dp[x]))
    return


# Solve
if __name__ == "__main__":
