def sieve(n):
    p = [True for i in range(n + 1)]
    p[0] = p[1] = False
    end = int(n**0.5)
    for i in range(2, end + 1):
        if p[i]:
            for j in range(i * i, n + 1, i):
                p[j] = False
    return p


def solve(n):
    if n < 2:
        return 0
    cnt = 1
    for i in range(3, n + 1, 2):
        if p[i]:
            cnt += 1
    return cnt


