from collections import defaultdict


def main():
    n = int(eval(input()))
    prime_counter = defaultdict(int)
    acc = tuple(accumulate(list(range(1, 42))))  # 10^12 < 2^39

    def facs():
        yield 2
        for x in range(10**6):
            yield x * 2 + 3

    for fac in facs():
