    for i in range(2, M):
        if sum(mp[i::i]) > 1:
            pairwise = 0
            break
    if pairwise:
        print("pairwise coprime")
    elif reduce(gcd, A) == 1:
        print("setwise coprime")
    else:
        print("not coprime")


if __name__ == "__main__":
    main()

