class BIT:
    def __init__(self, N):
        self.bit = [0] * (N + 1)
        self.N = N

    def add(self, a, w):
        x = a
        while x <= self.N:
            self.bit[x] += w
            x += x & (-x)

    def sum(self, a):
        ret = 0
        x = a
        while x > 0:
            ret += self.bit[x]
            x -= x & (-x)
        return ret


