# Summarize count of factor within list
def summarize_list(l):
    sl = sorted(l)
    a = sl[0]
    c = 1
    res = []
    for x in sl[1:]:
        if x == a:
            c += 1
        else:
            res.append([a, c])
            a = x
            c = 1
    res.append([a, c])
    return res


