class Factorial:
    def __init__(self, n, mod):
        self.mod = mod
        self.f = [1]
        for i in range(1, n + 1):
            self.f.append(self.f[-1] * i % mod)
        self.i = [pow(self.f[-1], mod - 2, mod)]
        for i in range(1, n + 1)[::-1]:
            self.i.append(self.i[-1] * i % mod)
        self.i.reverse()

