    def ifactorial(self, i):
        return self.i[i]

    def combi(self, n, k):
        return self.f[n] * self.i[n - k] % self.mod * self.i[k] % self.mod

    def permi(self, n, k):
        return self.f[n] * self.i[n - k] % self.mod


