K = 1024
N = 331
R = list(range(K))
B = [1, 2, 4, 8, 16, 32, 64, 128, 256, 512]
C = [0] * K
D = [[0 for i in range(N)] for j in R]


def init():
    global C, D
    for i in R:
        s = format(i, "b")
        n = s.count("1")
        C[i] = n
        if n == 1:
            D[i][B.index(i)] = 1
        else:
            for j in range(len(s)):
                if s[-j - 1] == "1":
                    dp = n * j
                    i2 = i - B[j]
                    for k in range(N - dp):
