from bisect import bisect_left, bisect_right

# 半開区間[lower, upper)の素数のリストを作成する
def make_prime_list(lower: int, upper: int) -> list:
    # 素数リストの初期化
    isPrime = [True] * upper
    primeList = []
    # 区間内の数字が0,1のみならここで終了
    if upper <= 2:
        return primeList
    # 区間内の数字に2以上のものがあるとき
    isPrime[0] = False
    isPrime[1] = False
    # エラトステネスの篩の処理
    for n in range(2, int(sqrt(upper)) + 2):
        if isPrime[n]:
            res = 2 * n
            while res < upper:
                isPrime[res] = False
                res += n
    # 区間内の素数を抽出
    for n in range(lower, upper):
        if isPrime[n]:
            primeList.append(n)
    return primeList


