def make_prime_list(lower: int, upper: int) -> list:
    if upper <= 2:
        return []
    prime_list = []
    is_prime = [True] * upper
    is_prime[0] = False
    is_prime[1] = False
    n = 2
    while n**2 < upper:
        if is_prime[n]:
            res = 2 * n
            while res < upper:
                is_prime[res] = False
                res += n
        n += 1
    for i in range(lower, upper):
        if is_prime[i]:
            prime_list.append(i)
    return prime_list


