def resolve():
    def prime(n):
        if n <= 1:
            return False
        A = [i for i in range(2, n + 1)]
        P = []
        lim = n**0.5
        while True:
            prime = A[0]
            if prime > lim:
                break
            P.append(prime)
            i = 0
            while i < len(A):
                if A[i] % prime == 0:
                    A.pop(i)
                    continue
                i += 1
        for a in A:
            P.append(a)
        return P

    C = 5 + 10**5
    S = [0] * C
    T = [0] * C
    for p in prime(C):
        S[p] = 1
    for i in range(C):
        if i % 2 == 0:
            continue
        if S[i] == 1 and S[(i + 1) // 2] == 1:
            T[i] = 1
    # cumsum
    for i in range(C - 1):
        T[i + 1] += T[i]
    # input
    q = int(eval(input()))
    for _ in range(q):
        l, r = list(map(int, input().split()))
        print((T[r] - T[l - 1]))


