def sigm(nk):
    s = 3**3 * (3 ** (nk - 2) - 1) / (3 - 1)
    s = s - 3 * 2**3 * (2 ** (nk - 2) - 1) / (2 - 1)
    s = s + (nk - 2) * 3
    return int(s)


