MOD = 10**9 + 7
X, Y = list(map(int, input().split()))


def powmod(a, p):
    if p == 0:
        return 1
    else:
        pow2 = powmod(a, p // 2)
        if p % 2 == 0:
            return (pow2**2) % MOD
        else:
            return (a * pow2**2) % MOD


def invmod(a):
    return powmod(a, MOD - 2)


def comb_mod(n, r):
    r = min(r, n - r)
    nPr = 1
    fact_r = 1
    for i in range(r):
        nPr *= n - i
        nPr %= MOD
        fact_r *= r - i
        fact_r %= MOD
    return (nPr * invmod(fact_r)) % MOD


