def search(u, g, visited):
    if visited[u]:
        return
    visited[u] = True
    for v in g[u]:
        search(v, g, visited)


def resolve():
    n, m = list(map(int, input().split()))
    edges = [list(map(int, input().split())) for _ in range(m)]
    ans = 0
    for i in range(m):
        g = [[] for _ in range(n)]
        for j in range(m):
            if i == j:
                continue
            a, b = edges[j]
            g[a - 1].append(b - 1)
            g[b - 1].append(a - 1)
        visited = [False] * n
        search(0, g, visited)
        if visited.count(True) != n:
            ans += 1
    print(ans)


resolve()

