def sieve(N):
    global table, prime
    table = [True] * (N + 1)
    table[0] = False
    table[1] = False
    prime = []
    for i in range(2, N + 1):
        if table[i]:
            prime.append(i)
            for j in range(2 * i, N + 1, i):
                table[j] = False


def accmulate(array):
    global cs
    cs = [0] * (len(array) + 1)
    for i in range(len(array)):
        cs[i + 1] = cs[i] + array[i]


def query(l, r):
    return cs[r + 1] - cs[l]


