    inf = 1 << 60
    D, G = list(map(int, input().split()))
    p = []
    c = []
    for i in range(D):
        pi, ci = list(map(int, input().split()))
        p.append(pi)
        c.append(ci)
    bitD = 1 << D
    min_cnt = inf
    for b in range(bitD):
        sc = 0
        cnt = 0
        for i in range(D):
            if (b & (1 << i)) != 0:
                sc += (i + 1) * 100 * p[i] + c[i]
