def think(h, k):
    cost = [0 for x in range(len(h))]
    for dst in range(1, len(h)):
        start_point = max(0, dst - k)
        cost[dst] = min(
            [cost[src] + abs(h[src] - h[dst]) for src in range(start_point, dst)]
        )
    return cost[len(h) - 1]


