def bpow(x, y, z):
    a = 1
    for b in format(y, "b"):
        a = (a * a) % z
        if b == "1":
            a = (a * x) % z
    return a


def solve(*args: str) -> str:
    n, m, k = list(map(int, args[0].split()))
    mod = 998244353
    if m == 1 and n - 1 == k:
        return str(1)
    ncr = 1
    p = m * bpow(m - 1, n - 1, mod) % mod
    ret = p
    inv = bpow(m - 1, mod - 2, mod)
    for i in range(1, k + 1):
        ncr = (ncr * (n - i) * bpow(i, mod - 2, mod)) % mod
        p = (p * inv) % mod
        ret += p * ncr % mod
    return str(ret % mod)


