def mcomb(n, k):
    if n == 0 and k == 0:
        return 1
    if n < k or k < 0:
        return 0
    return (
        fac[n]
        * pow(fac[n - k], 1000000005, 1000000007)
        * pow(fac[k], 1000000005, 1000000007)
        % 1000000007
    )


