from collections import deque
from copy import deepcopy


def factors(N):
    ret = []
    for i in range(2, int(N ** (1 / 2)) + 1):
        if N % i == 0:
            ret.append([])
            t = 1
            while N % i == 0:
                N //= i
                ret[-1].append(i**t)
                t += 1
    return ret


N = int(eval(input()))
