def getMinDiff(A, B):
    if A % 3 == 0:
        return 0
    elif B % 2 == 0:
        return B // 2
    else:
        ans = B  # 横3段に分ける場合の値
        # T字型に分ける場合
        for i in range(A % 3 + 1):
            A1 = A // 3 + i  # 上半分の縦幅
            B1, B2 = B // 2, (B + 1) // 2  # 下半分の左側、右側の横幅
            Ss = [A1 * B, (A - A1) * B1, (A - A1) * B2]
            ans = min(ans, max(Ss) - min(Ss))
        return ans


