        self.n = n
        self.bit = [0] * (n + 1)

    # bit_indexにxをO(log(n))で加算する
    def add(self, i, x):
        # if(i<=0 or i>n):return iに0以下の数字は代入しない
        while i <= self.n:
            self.bit[i] += x
            i += i & -i

    # bit_1 + bit_2 + …  + bit_n をO(log(n))で求める
    def sum(self, i):
        s = 0
        # iに0以下の数字は代入しない。
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s

    def rangesum(self, i, k):
        return self.sum(k) - self.sum(i)

    # a_1 + a_2 + … + a_i >= x となるような最小のiを求める(a_k >= 0)
    # xが0以下の場合は該当するものなし→0を返す
    def lower_bound(self, x):
        if x <= 0:
            return 0
        else:
            i = 0
            r = 1
            # 最大としてありうる区間の長さを取得する
            # n以下の最小の二乗のべき(BITで管理する数列の区間で最大のもの)を求める
            while r < self.n:
                r = r << 1
            len = r
            while len > 0:
                if i + len < self.n and self.bit[i + len] < x:
                    x -= self.bit[i + len]
                    i += len
                len = len >> 1
            return i + 1


def main():
    N, Q = MI()
    X, Y = BIT(N), BIT(N)
    xmin = N - 2
    ymin = N - 2
    X.add(1, N - 2)
    X.add(N - 1, -(N - 2))
    Y.add(1, N - 2)
    Y.add(N - 1, -(N - 2))
    res = (N - 2) ** 2
    for i in range(Q):
        a, b = MI()
        if a == 1:
            x = X.sum(b - 1)
            if ymin > b - 2:
                temp = Y.sum(1)
                Y.add(1, b - 2 - temp)
                Y.add(xmin + 1, -(b - 2 - temp))
                ymin = b - 2
            res -= x
        else:
            y = Y.sum(b - 1)
            if xmin > b - 2:
                temp = X.sum(1)
                X.add(1, b - 2 - temp)
                X.add(ymin + 1, -(b - 2 - temp))
                xmin = b - 2
            res -= y
    print(res)


if __name__ == "__main__":
    main()

