                s = 0
            else:
                s = 1
            return (
                subfunction(a, b, (a + 1) * (10 ** (digit - 1)) - 1)
                + subfunction(a, b, n % (10 ** (digit - 1)))
                + s
            )
        else:
            return subfunction(a, b, (b + 1) * (10 ** (digit - 1)) - 1)


