import sys

input = sys.stdin.readline
from collections import Counter


def main():
    n = int(eval(input()))
    cnt = Counter(list(map(int, input().rstrip().split())))
    ans = 0
    for i, j in list(cnt.items()):
        if i > j:
            ans += j
        elif i < j:
            ans += j - i
    print(ans)


if __name__ == "__main__":
    main()

