def dfs(n):
    if n < 6:
        return n
    elif n < 9:
        return 1 + dfs(n - 6)
    six_max = 1
    nine_max = 1
    while six_max * 6 <= n:
        six_max *= 6
    while nine_max * 9 <= n:
        nine_max *= 9
    return min(dfs(n - nine_max), dfs(n - six_max)) + 1


