from functools import reduce
import math
import itertools


def gcd(numbers):
    return reduce(lambda x, y: math.gcd(x, y), numbers)


def comb(K):
    return itertools.combinations_with_replacement(list(range(1, K + 1)), 3)


def main():
    k = int(eval(input()))
    if k == 1:
        print((1))
        return
    elif k == 2:
        print((9))
        return
    final = 0
    comb_list = list(comb(k))
    for i in comb_list:
        if len(set(i)) == 1:
            final += 1 * gcd(i)
        elif len(set(i)) == 2:
            final += 3 * gcd(i)
        else:
            final += math.factorial(3) * gcd(i)
    # print(comb_list)
    print(final)


main()

