    invFact[MAX - 1] = mod_inverse(fact[MAX - 1])
    for i in range(MAX - 2, -1, -1):
        invFact[i] = (invFact[i + 1] * (i + 1)) % MOD


def ncr(nn, rr):
    if nn < 0 or nn < rr or rr < 0:
        return 0
    return (fact[nn] * invFact[rr] * invFact[nn - rr]) % MOD


