def dfs(start, a, b, visited, n, graph):
    for node in graph[start]:
        if node not in visited:
            if (start, node) == (a, b) or (start, node) == (b, a):
                continue  # (start, node)がなくなっている場合を考えるので，このケースはスルーする
            else:
                visited.append(node)
                dfs(node, a, b, visited, n, graph)
    if len(visited) == n:
        return 0
    else:
        return 1


def main():
    N, M = list(map(int, input().split()))
    graph = [[] for _ in range(N)]
    edge = []
    for _ in range(M):
        a, b = list(map(int, input().split()))
        a, b = a - 1, b - 1
        graph[a].append(b)
        graph[b].append(a)
        edge.append((a, b))
    cnt = 0
    for a, b in edge:
        cnt += dfs(0, a, b, [], N, graph)
    print(cnt)


if __name__ == "__main__":
    main()

