def main():
    n, a, b = list(map(int, input().split()))
    MOD = 10**9 + 7
    s = pow(2, n, MOD) - 1
    print((comb_mod(n, MOD, a, b, s)))


def comb_mod(n, mod, a, b, s):
    numerator = 1
    denominator = 1
    for i in range(b):
        numerator = (numerator * (n - i)) % mod
        denominator = (denominator * (i + 1)) % mod
        if i == a - 1 or i == b - 1:
            s = s - (numerator * pow(denominator, mod - 2, mod)) % mod
    return s % mod


