def pow_r_mod(x: int, n: int, mod=10**9 + 7) -> int:
    # 計算量 : log N
    if n == 0:
        return 1
    K = 1
    while n > 1:
        if n % 2 != 0:
            K *= x
        x *= x
        x %= mod
        n //= 2
    return (K * x) % mod


def mod_pow(a: int, b: int, mod: int) -> int:
    if b % 2 == 0:
        return (mod_pow(a, b // 2, mod) ** 2) % mod
    elif b == 1:
        return a % mod
    else:
        return ((mod_pow(a, b // 2, mod) ** 2) * a) % mod


