from sys import stdin
from copy import deepcopy
import queue


class Dice:
    def __init__(self, nums):
        self.labels = [None] + [nums[i] for i in range(6)]
        self.pos = {"E": 3, "W": 4, "S": 2, "N": 5, "T": 1, "B": 6}

    def rolled(dice, queries):
        d = deepcopy(dice)
        for q in queries:
            if q == "E":
                d.pos["T"], d.pos["E"], d.pos["B"], d.pos["W"] = (
                    d.pos["W"],
                    d.pos["T"],
                    d.pos["E"],
                    d.pos["B"],
                )
            elif q == "W":
                d.pos["T"], d.pos["E"], d.pos["B"], d.pos["W"] = (
                    d.pos["E"],
                    d.pos["B"],
                    d.pos["W"],
                    d.pos["T"],
                )
            elif q == "S":
                d.pos["T"], d.pos["S"], d.pos["B"], d.pos["N"] = (
                    d.pos["N"],
                    d.pos["T"],
                    d.pos["S"],
                    d.pos["B"],
                )
            elif q == "N":
                d.pos["T"], d.pos["S"], d.pos["B"], d.pos["N"] = (
                    d.pos["S"],
                    d.pos["B"],
                    d.pos["N"],
                    d.pos["T"],
                )
        else:
            return d


