def solve():
    H, N = list(map(int, input().split()))
    attack = []
    mp = []
    for i in range(N):
        a, b = list(map(int, input().split()))
        attack.append(a)
        mp.append(b)
    max_attack = max(attack)
    dp = [[float("inf")] * (H + max_attack) for _ in range(N + 1)]
    for i in range(N + 1):
        dp[i][0] = 0
    for i in range(N):
        for j in range(H + max_attack):
            if j - attack[i] >= 0:
                dp[i + 1][j] = min(
                    dp[i + 1][j],
                    dp[i][j - attack[i]] + mp[i],
                    dp[i + 1][j - attack[i]] + mp[i],
                )
            dp[i + 1][j] = min(dp[i + 1][j], dp[i][j])
    ans = float("inf")
    for i in range(N + 1):
        for j in range(H, H + max_attack):
            ans = min(ans, dp[i][j])
    print(ans)


if __name__ == "__main__":
