def main():
    n, m = LI()
    if n == 1:
        return 1
    e = collections.defaultdict(list)
    for _ in range(n - 1):
        a, b = LI_()
        e[a].append(b)
        e[b].append(a)
    rr = [None] * n
    fm = [None] * n

    def f(i, p):
        r = 1
        for c in e[i]:
            if c != p:
                r *= f(c, i) + 1
                r %= m
