        aa = [None] * l
        aa[0] = ta[0]
        for j in range(1, l):
            aa[j] = aa[j - 1] * ta[j] % m
        ba = [None] * l
        ba[-1] = ta[-1]
        for j in range(l - 2, -1, -1):
            ba[j] = ba[j + 1] * ta[j] % m
        rr[i] = ba[0] % m
        if v[0] != p:
            g(v[0], i, ba[1])
        for j, u in enumerate(v[1:-1]):
            if u != p:
                g(u, i, aa[j] * ba[j + 2] % m)
        if v[-1] != p:
            g(v[-1], i, aa[-2])

    def h(i):
        l = len(e[i])
        v = e[i]
        ta = [(fm[u] if not fm[u] is None else f(u, i)) + 1 for u in v]
        if l == 1:
            rr[i] = ta[0] % m
