def read_str_n():
    return readline().strip().split()


def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()
        error_print(e - s, "sec")
        return ret

    return wrap


@mt
def slv(N, A):
    from collections import Counter

    c = Counter()
    ma = max(A)
    for a in A:
        for i in range(ma // a + 1):
            c[a * i] += 1
    ans = 0
    for a in A:
        if c[a] == 1:
            ans += 1
    return ans


