                x = 5 - u % 5
                v = (u + x) // 5
                if cost + c + d * x < dist[v]:
                    dist[v] = cost + c + d * x
                    heappush(que, (cost + c + d * x, v))
        if u >= 3:
            x = u % 3
            v = (u - x) // 3
            if cost + b + d * x < dist[v]:
                dist[v] = cost + b + d * x
                heappush(que, (cost + b + d * x, v))
            if u % 3 != 0:
                x = 3 - u % 3
                v = (u + x) // 3
                if cost + b + d * x < dist[v]:
                    dist[v] = cost + b + d * x
                    heappush(que, (cost + b + d * x, v))
        if u >= 2:
            x = u % 2
            v = (u - x) // 2
            if cost + a + d * x < dist[v]:
                dist[v] = cost + a + d * x
                heappush(que, (cost + a + d * x, v))
            if u % 2 != 0:
                x = 2 - u % 2
                v = (u + x) // 2
                if cost + a + d * x < dist[v]:
                    dist[v] = cost + a + d * x
                    heappush(que, (cost + a + d * x, v))
    return dist


