    for i in range(MAX, 2 * MAX):
        y_comp[uf.find(i)] += 1
    ans = 0
    for k in list(x_comp.keys()):
        ans += x_comp[k] * y_comp[k]
    ans -= N
    print(ans)
    return


if __name__ == "__main__":
