from itertools import combinations
from math import gcd


def func(A):
    is_A = [0] * (10**6 + 1)
    for a in A:
        is_A[a] += 1
    if any(x > 1 for x in is_A[2:]):
        return False
    n = 0
    for i in range(2, 10**6 + 1, 2):
        if is_A[i]:
            n += 1
    if n > 1:
        return False
    for i in range(3, 10**6 + 1, 2):
        n = 0
        for j in range(i, 10**6 + 1, i):
            if is_A[j]:
                n += 1
        if n > 1:
            return False
    return True


