    if func(A):
        # if not all(gcd(i, j)==1 for i, j in combinations(A, 2)):
        #     raise NameError
        print("pairwise coprime")
    elif reduce(gcd, A) == 1:
        print("setwise coprime")
    else:
        print("not coprime")


if __name__ == "__main__":
