def GCD(a, b):
    while b != 0:
        a, b = b, a % b
    return a


def LCM(a, b):
    return a * b // GCD(a, b)


def Eratosthenes(N):
    r = [True] * (N + 1)
    r[0] = False
    r[1] = False
    i = 2
    while i * i <= N:
        if r[i]:
            j = i
            while i * j <= N:
                r[i * j] = False
                j += 1
        i += 1
    return r


