from itertools import accumulate

Q = int(eval(input()))


def prime(n):
    # 素数列挙
    # nまでの素数をリストで返す(nを含む)
    primes = set(range(2, n + 1))
    for i in range(2, int(n**0.5 + 1)):
        primes.difference_update(list(range(i * 2, n + 1, i)))
    primes = list(primes)
    return primes


