        r = min(r, n - r)
        return self.g1[n] * self.g2[r] * self.g2[n - r] % self.MOD


@mt
def slv(N, K):
    C = Combination(N * 2, 10**9 + 7)
    ans = 0
    for i in range(0, min(K + 1, N)):
        r = N - i
        t = M.mul(C(N, i), C(r + i - 1, i))
        ans = M.add(ans, t)
    return ans


def main():
    N, K = read_int_n()
    print(slv(N, K))


if __name__ == "__main__":
    main()

