def f(n):
    m = int(math.sqrt(n) + 0.5)
    res = 0
    for x in range(1, m + 1):
        for y in range(x, m + 1):
            k = n - (x * x + y * y + x * y)
            if k < 1:
                break
            l = y
            r = m + 1
            while r - l > 1:
                z = (r + l) // 2
                tmp = (x + y + z) * z
                if tmp <= k:
                    l = z
                else:
                    if r == z + 1:
                        r -= 1
                    else:
                        r = z + 1
            if (x + y + l) * l == k:
                s = set()
                s.add(x)
                s.add(y)
                s.add(l)
                if len(s) == 3:
                    res += 6
                elif len(s) == 2:
                    res += 3
                else:
                    res += 1
    return res


