def n_ary(l, d):  # リストl中の文字でd桁までを全列挙(sorted)
    if d == 1:
        return l
    n = len(l)
    ll = n_ary(l, d - 1)
    lll = []
    for i in l:
        for j in ll[n * (n ** (d - 2) - 1) // (n - 1) :]:
            lll.append(i + j)
    return ll + lll


