def get_divisor(n):
    a, b = [], []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            a.append(i)
            b.append(n // i)
    if a[-1] == b[-1]:
        b.pop()
    a.extend(b[::-1])
    return a


