    if tmp != li[i]:
        countli.append(count)
        count = 1
    else:
        count += 1
    tmp = li[i]
countli.append(count)
ans = 1
for i in range(len(countli)):
    ans *= combinations_count(countli[i] + n - 1, countli[i])
