# NlogNダイクストラ
# これも最短経路を求める問題
def dijkstra(n, start):
    dist = [float("inf")] * n
    pos = [(0, start)]
    heapify(pos)
    dist[start] = 0
    while len(pos):
        cost, u = heappop(pos)
        if dist[u] < cost:
            continue
        # エッジは探索のたびに生成していく
        for i in range(len(coin)):
            if u + coin[i] >= n:
                continue
            if dist[u] + 1 < dist[u + coin[i]]:
                dist[u + coin[i]] = dist[u] + 1
                heappush(pos, (dist[u] + 1, u + coin[i]))
    return dist


