#!/usr/bin/env python3
# ABC122 D
# 条件を満たさないものは以下の5通りで追加する文字列+3文字を見れば決まる
# ACG,GAC,AGC,A?GC,AG?C
n = int(eval(input()))
# メモ化再帰
memo = [{} for i in range(n + 1)]
mod = 10**9 + 7


def ok(last4):
    for i in range(4):
        t = list(last4)
        if i >= 1:
            t[i - 1], t[i] = t[i], t[i - 1]
        if "".join(t).count("AGC") >= 1:
            return False
    return True


def dfs(cur, last3):
    if last3 in memo[cur]:
        return memo[cur][last3]
    if cur == n:
        return 1
    ret = 0
    # AGCTを1文字ずつ追加してみる
    for c in "AGCT":
        # cを追加したときにTrue(不適でない)なら
        if ok(last3 + c):
            # 現在位置を1つ進めてcを追加した値を足す
            ret = (ret + dfs(cur + 1, last3[1:] + c)) % mod
    # 値を格納
    memo[cur][last3] = ret
    return ret


