import math


def Sieve_of_Eratosthenes(N):
    prime = {}
    for i in range(2, N + 1):
        prime[i] = 1
    for i in range(2, math.ceil(N**0.5) + 1):
        tmp = set()
        for j in prime:
            if j > i and j % i == 0:
                tmp.add(j)
        for j in tmp:
            prime.pop(j)
    return prime


