        cnt = 0
        # 時刻ごとにそれぞれのチャンネルで録画機を使ってるかどうか数え上げる
        for ch in range(C):
            if R[ch][t] == 1:
                cnt += 1
        ans = max(ans, cnt)
    print(ans)


