        SCORE[i][j] = 0
        return
    if SCORE[i][j] != None:
        return SCORE[i][j] + k
    if l == 1:
        SCORE[i][j] = max(SCORE[i + 1][j] + A[i], SCORE[i][j - 1] + A[j - 1]) - k
    else:
        SCORE[i][j] = min(SCORE[i + 1][j] - A[i], SCORE[i][j - 1] - A[j - 1]) - k


