    input = sys.stdin.readline
    N, M = list(map(int, input().split()))
    uf = UnionFindTree(N)
    for _ in range(M):
        x, y, z = list(map(int, input().split()))
        uf.union(x - 1, y - 1)
    c = set([uf.find(i) for i in range(N)])
