import math as ma

MOD = 10**9 + 7


def inv(a):
    return pow(a, MOD - 2, MOD)


def comb(n, r, MOD):
    ans = ma.factorial(n) % MOD * inv(ma.factorial(r)) * inv(ma.factorial(n - r))
    return ans % MOD


def prime(n):
    ans = []
    for i in range(2, int(n**0.5) + 1):
        while not n % i:
            n //= i
            ans.append(i)
    if n != 1:
        ans.append(n)
    return ans


