def solve():
    s, t = read()
    result = think(s, t)
    write(result)


def read():
    return read_line(), read_line()


def read_int(n):
    return list([int(x) for x in read_line().split(" ")])[:n]


def read_line(n=0):
    if n == 0:
        return input().rstrip()
    else:
        return input().rstrip()[:n]


def think(s, t):
    # create dp table
    local_s = " " + s  # for convenience
    local_t = " " + t
    dp = [[0 for x in range(len(local_s))] for y in range(len(local_t))]
    for y, ct in enumerate(local_t):
        for x, cs in enumerate(local_s):
            if x == 0 or y == 0:
                dp[y][x] = 0
            else:
                if local_s[x] == local_t[y]:
                    dp[y][x] = dp[y - 1][x - 1] + 1
                else:
                    dp[y][x] = max(dp[y - 1][x], dp[y][x - 1], dp[y - 1][x - 1])
    # scan dp table backward
    x = len(dp[0]) - 1
    y = len(dp) - 1
    buf = ""
    while x > 0 and y > 0:
        if local_s[x] == local_t[y]:
            buf += local_s[x]
            x -= 1
            y -= 1
        else:
            if dp[y][x] == dp[y - 1][x]:
                y -= 1
            else:
                x -= 1
    buf = list(buf)
    buf.reverse()
    return "".join(buf)


def write(result):
    print(result)


if __name__ == "__main__":
    solve()

