def yakusu(x):
    xx = 2
    y = []
    while xx**2 < x:
        if x % xx == 0:
            y.append(xx)
            y.append(x // xx)
        xx += 1
    if xx**2 == x:
        y.append(xx)
    y.append(x)
    return y


