def primes(N):
    sieve = [True] * (N + 1)
    sieve[:2] = [False, False]
    for i in range(4, N + 1, 2):
        sieve[i] = False
    for i in range(3, N + 1, 2):
        if sieve:
            for j in range(2 * i, N + 1, i):
                sieve[j] = False
    P = []
    for i in range(N + 1):
        if sieve[i]:
            P.append(i)
    return P


