sys.setrecursionlimit(10000)


def read_int():
    return int(input())


def read_int_n():
    return list(map(int, input().split()))


def read_float():
    return float(input())


def read_float_n():
    return list(map(float, input().split()))


def read_str():
    return input().strip()


def read_str_n():
    return list(map(str, input().split()))


def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()
        error_print(e - s, "sec")
        return ret

    return wrap


def Prim(g):
    V = list(g.keys())
    for v in g.values():
        V.extend(list(v.keys()))
    V = list(set(V))
    used = set([])
    q = []
    heapq.heappush(q, (0, V[0]))
    ret = 0
    while q:
        c, v = heapq.heappop(q)
        if v in used:
            continue
        used.add(v)
        ret += c
        for u in g[v]:
            heapq.heappush(q, (g[v][u], u))
    return ret


@mt
def slv(N, A, B, H):
    H.sort(reverse=True)

    def e(t):
        b = B * t
        a = A - B
        for h in H:
            h -= b
            if h > 0:
                t -= int(math.ceil(h / a))
        return t >= 0

    l = 0
    r = max(H)
    while r - l > 1:
        m = (r + l) // 2
        if e(m):
            r = m
        else:
            l = m
    return r


def main():
    N, A, B = read_int_n()
    H = [read_int() for _ in range(N)]
    print(slv(N, A, B, H))


if __name__ == "__main__":
    main()

