def pow(n, x):
    if x == 0:
        return 1
    elif x % 2 == 0:
        return pow(n * n % mod, x // 2)
    else:
        return n * pow(n * n % mod, x // 2) % mod


def comb(n, r):
    p, q = 1, 1
    for i in range(r):
        p = p * (n - i) % mod
        q = q * (i + 1) % mod
    return p * pow(q, mod - 2) % mod


