import sys


def furui(n):
    l = [1 for i in range(n + 1)]
    l[0] = 0
    l[1] = 0
    for i in range(2, n + 1):
        if l[i] == 1:
            for j in range(2, n // i + 1):
                l[i * j] = 0
    l2 = []
    for i in range(len(l)):
        if l[i] == 1:
            l2.append(i)
    return l2


