#!/usr/bin/env python3
import sys
import math


def solve(K: int):
    answer = 0
    GCDLIST = [[1] * (K + 1) for _ in range(K + 1)]
    for i in range(1, K + 1):
        for j in range(1, K + 1):
            g = math.gcd(i, j)
            GCDLIST[i][j] = g
            GCDLIST[j][i] = g
    for i in range(1, K + 1):
        for j in range(1, K + 1):
            for k in range(1, K + 1):
                answer += GCDLIST[GCDLIST[i][j]][k]
    print(answer)
    return


