def factorization(n):
    lis = []
    if n % 2 == 0:
        c = 0
        while n % 2 == 0:
            n //= 2
            c += 1
        lis.append([2, c])
    k = 3
    while k * k <= n:
        if n % k == 0:
            c = 0
            while n % k == 0:
                n //= k
                c += 1
            lis.append([k, c])
        else:
            k += 2
    if n > 1:
        lis.append([n, 1])
    return lis


