"""
解説参考
・まず素因数分解で階乗全部バラす
・そこからいい感じの組み合わせを探して数える
"""
N = int(eval(input()))
# 階乗の素因数分解：ひとつずつ分解したものを合算
e = [0] * (N + 1)
# 階乗の各値ループ
for i in range(2, N + 1):
    num = i
    # 素因数分解するループ
    for j in range(2, N + 1):
        while num % j == 0:
            num //= j
