def bellmanford(n, edges, start):
    INF = float("inf")
    dist = [-INF] * (n + 1)  # dist[0]は使わない
    dist[start] = 0
    for i in range(n):
        for (pre, ne, weight) in edges:
            if dist[pre] != -INF and dist[pre] + weight > dist[ne]:
                dist[ne] = dist[pre] + weight
                if i == n - 1 and ne == n:
                    return "inf"
    return dist[n]


